const menu=[['home','الرئيسية','home'],['lessons','مساحة الدرس','book'],['schedule','الحصص والجدول','calendar'],['classes','الصفوف والطالبات','users'],['assignments','التدريب والتقييم','list'],['skills','مختبر المهارات','target'],['library','الكتب والملفات','file'],['games','الألعاب والتحفيز','game'],['reports','التقارير والشهادات','chart'],['parents','أولياء الأمور','heart'],['tools','أدوات المعلمة','grid']];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('امتلأت مساحة حفظ المتصفح؛ صدّري بياناتك')}document.body.classList.toggle('dark',!!state.dark)}function setBoard(changes){state.board={...state.board,...changes};persist();try{localStorage.setItem(BOARD,JSON.stringify(state.board));boardChan?.postMessage(state.board)}catch{} }function toast(t){let n=$('#toast');n.textContent=t;n.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>n.classList.remove('show'),2600)}const button=(label,action,cls='softbtn')=>`<button class="${cls}" data-act="${action}">${label}</button>`,dateText=()=>new Intl.DateTimeFormat('ar-SA',{dateStyle:'full'}).format(new Date()),hijri=()=>{try{return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}catch{return ''}},className=cid=>state.classes.find(c=>c.id===cid)?.name||'فصل محذوف';
function tday(t){return t.type==='routine'?(t.doneOn===iso()):!!t.done}function taskList(limit=5,filter='all'){let tasks=state.tasks.filter(t=>filter==='all'||filter==='done'&&tday(t)||t.type===filter).filter(t=>filter==='all'||filter==='done'||!tday(t)).sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||b.priority-a.priority);if(limit)tasks=tasks.slice(0,limit);return tasks.length?`<ul class="list-clean">${tasks.map(t=>`<li class="taskitem"><button class="check ${tday(t)?'checked':''}" data-toggle-task="${esc(t.id)}" aria-label="تحديد الإنجاز">${tday(t)?ic('check',12):''}</button><div class="copy"><b class="${tday(t)?'finished':''}">${esc(t.title)}</b><small>${t.type==='routine'?'تتجدد كل يوم':t.type==='weekly'?'هذا الأسبوع':t.date?esc(t.date):'مهمة يومية'} ${t.pinned?' · مثبّتة':''}</small></div>${t.priority>1?`<span class="priority">${'!'.repeat(t.priority)}</span>`:''}<button class="light-more" data-edit-task="${esc(t.id)}" title="تعديل">${ic('edit',15)}</button></li>`).join('')}</ul>`:'<div class="empty">ما فيه مهام هنا الآن. يومك أهدأ ✿</div>'}
function timed(){let d=new Date(),now=d.getHours()*60+d.getMinutes()+d.getSeconds()/60,ds=state.schedule.filter(x=>x.day===d.getDay()||x.day===7).sort((a,b)=>a.start.localeCompare(b.start)),m=t=>+t.slice(0,2)*60 + +t.slice(3);let active=ds.find(x=>now>=m(x.start)&&now<m(x.end));let next=ds.find(x=>m(x.start)>now);return {ds,lesson:active||next,active:!!active,minutes:active?m(active.end)-now:next?m(next.start)-now:0,now};}function fmt(n){n=Math.max(0,Math.floor(n*60));return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function mins(value){let [hours,minutes]=String(value||"00:00").split(":").map(Number);return (hours||0)*60+(minutes||0)}
function dateCalendar(){let today=new Date(),start=new Date(today.getFullYear(),today.getMonth(),1),daysCount=new Date(today.getFullYear(),today.getMonth()+1,0).getDate(),offset=(start.getDay()+1)%7;let html=['س','ح','ن','ث','ر','خ','ج'].map(x=>`<span class="weekday">${x}</span>`).join('');for(let j=0;j<offset;j++)html+='<span class="blank">0</span>';for(let j=1;j<=daysCount;j++){let v=iso(new Date(today.getFullYear(),today.getMonth(),j)),ev=state.events.some(x=>x.date===v);html+=`<button class="${j===today.getDate()?'today':''} ${ev?'event':''}" data-act="calendar" title="${v}">${j}</button>`}return html}
const flower=`<svg class="dayflower" viewBox="0 0 100 100" fill="none" aria-hidden="true"><path d="M50 50c-20-13-23-35-6-37 12-2 14 18 6 37Z" fill="#a4c9d6"/><path d="M50 50c9-22 29-33 36-17 5 11-16 23-36 17Z" fill="#b2dfd3"/><path d="M50 50c22 2 35 22 22 33-10 8-25-9-22-33Z" fill="#c9d7ee"/><path d="M50 50c-11 22-34 28-40 12-5-13 15-23 40-12Z" fill="#ead9be"/><circle cx="50" cy="50" r="9" fill="#f8f9fb"/><circle cx="50" cy="50" r="5" fill="#6e9ba9"/></svg>`;

function navbtn(p,n,i){return `<button class="${page===p?'active':''}" data-go="${p}">${ic(i,19)} <span>${esc(n)}</span></button>`}
function nav(){return `<aside class="rail" id="rail"><div class="logo"><div class="logo-mark">م</div><div><strong>مساحة</strong><small>لكل يوم دراسي حكاية</small></div></div><span class="rail-label">المعلمة</span><nav class="nav">${menu.slice(0,4).map(([p,n,i])=>navbtn(p,n,i)).join('')}</nav><span class="rail-label">المحتوى والتجهيز</span><nav class="nav">${menu.slice(4,8).map(([p,n,i])=>navbtn(p,n,i)).join('')}</nav><span class="rail-label">المتابعة</span><nav class="nav">${menu.slice(8).map(([p,n,i])=>navbtn(p,n,i)).join('')}</nav><div class="rail-bottom"><nav class="nav"><button data-act="student-portal">${ic('heart',18)} واجهة الطالبة</button><button data-act="parent-portal">${ic('users',18)} ولي الأمر</button><button data-act="settings">${ic('settings',18)} الإعدادات</button></nav><div class="profile-mini"><span class="avatar">م</span><span>${esc(state.teacher)}<small>${esc(state.school)}</small></span></div></div></aside>`}
function layout(content){return `<div class="shell">${nav()}<main class="workspace"><header class="topline"><div class="row">${button(ic('menu',18),'menu','iconbutton mobile-toggle')}<span class="bread">مساحة / ${esc(menu.find(x=>x[0]===page)?.[1]||'الرئيسية')}</span></div><div class="topcontrols"><span class="date-line">${esc(hijri())}</span><button class="iconbutton" data-go="calendar" aria-label="التقويم الدراسي" title="التقويم الدراسي">${ic('calendar',19)}</button><button class="iconbutton" data-go="alerts" aria-label="التنبيهات">${ic('bell',19)}</button><button class="iconbutton" data-act="settings" aria-label="الإعدادات">${ic('settings',19)}</button></div></header>${content}<footer class="small-print mt" style="padding-top:30px">مساحة · نموذج تفاعلي للتطوير · الحسابات والبيانات الحقيقية تحتاج تشغيل الخادم وصلاحياته</footer></main></div>`}
const header=(title,caption,actions='')=>`<header class="page-header"><div><span class="section-kicker">إدارة المعلمة</span><h1>${title}</h1><p>${caption}</p></div><div class="row">${actions}</div></header>`;
function home(){const t=timed(),l=t.lesson,c=className(l?.classId);return `<section class="welcome new-welcome"><div><span class="section-kicker">${esc(dateText())} <span class="soft-point">·</span> ${esc(hijri())}</span><h1>${new Date().getHours()<12?'صباح النور':'مساء النور'}، ${esc(state.teacher)}</h1><p>${esc(state.phrase)}</p><div class="welcome-actions">${button(ic('book',16)+' افتحي مساحة الدرس','lessons','solid')}${button('ترتيب الرئيسية','settings','softbtn')}</div></div><div class="welcome-art" aria-hidden="true"><span class="arc a"></span><span class="arc b"></span><span class="paper-pencil">✎</span><span class="dot a"></span><span class="dot b"></span></div></section><div class="dashboard-flow new-dashboard"><div class="mainstack"><section><div class="line-heading"><h2>الحصة في وقتها</h2>${button('الجدول الكامل','schedule','textbutton')}</div><div class="lesson-feature smart-feature"><div class="feature-meta"><i class="pulse"></i>${l?(t.active?'الحصة الآن':'الحصة القادمة'):'انتهت حصص اليوم'} ${l?'· '+esc(l.start)+' – '+esc(l.end):''}</div><div class="feature-main"><div><span class="section-kicker">${l?esc(c):'يمكنك تجهيز الغد'}</span><h2>${l?esc(l.topic||l.title):'مساحة هادئة لترتيب يومك'}</h2><p>${l?'حضّري الدرس، ثم اختاري ما يظهر للطالبات خطوة خطوة':'الجدول قابل للتعديل في أي وقت'}</p></div><div class="countdown" id="homeCountdown">${l?fmt(t.minutes):'00:00:00'}<small>${l?t.active?'حتى نهاية الحصة':'حتى بداية الحصة':'لا يوجد عداد'}</small></div></div><div class="feature-bottom"><span class="pill">${ic('clock',13)} ${l?esc(c):'يوم جديد'}</span>${button('بدء تجهيز الحصة '+ic('arrow',15),'lessons','solid')}</div><div class="progress-track"><i id="lessonProgress" style="width:${t.active&&l?Math.min(100,100*(1-t.minutes/(mins(l.end)-mins(l.start)))):0}%"></i></div></div></section>${state.show.timeline?`<section><div class="line-heading"><h2>تسلسل اليوم</h2><span class="sub">حسب أوقات الجدول</span></div><div class="timeline">${t.ds.length?t.ds.map(x=>`<button class="slot ${l?.id===x.id?'active':''}" data-act="schedule"><small>${esc(x.start)} – ${esc(x.end)}</small><strong>${esc(className(x.classId))}</strong><em>${esc(x.topic)}</em></button>`).join(''):'<p class="muted">ما عندك حصص مجدولة اليوم.</p>'}</div></section>`:''}${state.show.tools?`<section><div class="line-heading"><h2>من هنا تبدئين</h2></div><div class="quickbar">${[['lessons','تحضير الدرس','book'],['library','الكتب والملفات','file'],['classes','كشف الطالبات','users'],['skills','تدريب المهارات','target'],['games','الأنشطة','game']].map(([x,n,i])=>`<button data-go="${x}" class="quick-action">${ic(i,20)}<span>${n}</span></button>`).join('')}</div></section>`:''}</div><div class="sidestack">${state.show.tasks?`<section><div class="line-heading"><h2>على بالك اليوم</h2>${button('الصفحة الكاملة','tasks','textbutton')}</div><div class="dropbox smart-tasks"><button class="drop-head" data-act="toggle-hometasks" aria-expanded="true" aria-controls="homeTasks"><span>المهام والروتين</span><span id="taskArrow">⌄</span></button><div class="drop-content" id="homeTasks">${taskList(4)}<div class="task-actions">${button(ic('plus',13)+' مهمة','add-task','softbtn')}${button('عرض موسّع','tasks','textbutton')}</div></div></div></section>`:''}${state.show.notices?`<section><div class="line-heading"><h2>ما يحتاج انتباهك</h2>${button('كل التنبيهات','alerts','textbutton')}</div><div class="gentle-notices">${state.alerts.slice(-2).map(a=>`<div class="notice-line"><i class="notice-dot"></i><div><b>${esc(a.text)}</b><small>${a.date?esc(a.date):'لليوم الدراسي'}</small></div></div>`).join('')||'<span class="muted">كل شيء تحت السيطرة.</span>'}</div></section>`:''}<section class="little-note"><span class="section-kicker">ملاحظة خاصة بك</span><p>${esc(state.teacherNotes.at(-1)?.text||'فكرة صغيرة اليوم قد تصبح طريقة شرح جميلة غدًا.')}</p>${button('أضيفي ملاحظة','add-note','textbutton')}</section></div></div>`}
function schedule(){return header('جدول حصصك','الأوقات من اختيارك، وعدّاد الرئيسية يتبعها مباشرة.',button(ic('plus',15)+' إضافة حصة','add-schedule','solid'))+`<div class="page-body"><div class="paper"><div class="row mb">${days.map((day,i)=>`<button class="chip ${chosenDay===i?'selected':''}" data-day="${i}">${day}</button>`).join('')}</div>${state.schedule.filter(x=>x.day===chosenDay||x.day===7).sort((a,b)=>a.start.localeCompare(b.start)).map(x=>`<div class="lesson-row"><div class="number-marker">${ic('clock',17)}</div><div class="grow"><b>${esc(x.topic||x.title)}</b><small>${esc(className(x.classId))} · ${esc(x.start)} – ${esc(x.end)}</small></div>${button('تعديل','edit-schedule:'+x.id,'textbutton')}${button('حذف','delete-schedule:'+x.id,'textbutton warntext')}</div>`).join('')||'<div class="empty">لا توجد حصص لهذا اليوم</div>'}</div><div class="notice">العد التنازلي يعرض الحصة الحالية أو التالية حسب تاريخ الجهاز ووقته. لا يتم افتراض جدول رسمي.</div></div>`}let chosenDay=new Date().getDay();
function classes(){return header('فصولي وطالباتي','كشف منظم للحضور، المشاركة، المجموعات والمقاعد.',button(ic('plus',14)+' فصل جديد','add-class','solid')+button('إضافة طالبة','add-student','softbtn'))+`<div class="page-body"><div class="paper"><div class="row mb">${state.classes.map(c=>`<button class="chip ${c.id===classId?'selected':''}" data-class="${esc(c.id)}">${esc(c.name)} · ${state.students.filter(s=>s.classId===c.id).length}</button>`).join('')}</div><div class="activity-strip mb"><span>الحضور اليوم · ${esc(className(classId))}</span>${button('بدء كشف الحضور','attendance','solid')}</div><div class="table-wrap"><table><thead><tr><th>الطالبة</th><th>نقاط التشجيع</th><th>الحضور</th><th>إجراء</th></tr></thead><tbody>${state.students.filter(s=>s.classId===classId).map((s,i)=>{let at=state.attendance.find(a=>a.studentId===s.id&&a.date===iso());return `<tr><td>${i+1}. ${esc(s.name)}</td><td>${s.points||0}</td><td>${at?`<span class="tag ${at.present?'good':'warn'}">${at.present?'حاضرة':'غائبة'}</span>`:'<span class="tag">لم يُرصد</span>'}</td><td>${button('+ نقطة','point:'+s.id,'textbutton')}${button('تعديل','edit-student:'+s.id,'textbutton')}</td></tr>`}).join('')||'<tr><td colspan="4">الفصل فارغ</td></tr>'}</tbody></table></div></div><div class="two-cards"><div class="paper"><h3>المجموعات</h3><p class="muted">توزيع مرن للطالبات في مجموعات متقاربة العدد</p><div class="row">${[2,3,4,5].map(n=>button(n+' فرق','groups:'+n,'softbtn')).join('')}</div><div id="groupsResult" class="mt"></div></div><div class="paper"><h3>المقاعد</h3><p class="muted">عرض مقاعد أولي مرتبط بالفصل المختار</p><div class="tools-grid">${state.students.filter(s=>s.classId===classId).map(s=>`<div class="tool-tile" style="min-height:72px">${ic('users',16)}${esc(s.name)}</div>`).join('')}</div></div></div></div>`}
const sceneTypes=[['warmup','بداية وترحيب'],['rules','قواعد الصف'],['review','مراجعة ما سبق'],['hook','تهيئة وتفكير'],['goals','أهداف الدرس'],['explain','شرح المفهوم'],['example','مثال محلول'],['activity','نشاط وتعاون'],['practice','تدريب فردي'],['check','تقويم مرحلي'],['exit','تذكرة خروج'],['homework','واجب منزلي'],['custom','مشهد حر']];
const baseScenes=()=>[['warmup','أهلًا يا مبدعات','نبدأ يومنا بفكرة جميلة.',''],['rules','اتفاقنا الجميل','نستمع · نشارك · نحاول · نحترم بعضنا',''],['review','نتذكر معًا','ماذا تعلمنا في الحصة السابقة؟',''],['goals','ماذا سنتعلم؟','اكتبي أهداف الدرس هنا.',''],['explain','نكتشف الفكرة','اشرحي المفهوم خطوة خطوة مع مثال واضح.',''],['activity','حان دورك','تدريب خفيف أو نشاط جماعي.',''],['exit','قبل أن نغادر','ماذا فهمنا اليوم؟','']].map(([type,title,text,answer])=>({id:id(),type,title,text,answer}));
function ensureLessonExtras(l){if(!l.scenes)l.scenes=baseScenes();if(!l.preparation)l.preparation={strategies:'',materials:'',assessment:'',differentiation:'',values:'',homework:'',prerequisites:'',introduction:''};if(!l.resources)l.resources=[];return l}
function lessons(){return header('مساحة الدرس','ابدئي من اختيار الدرس. التحضير والمصادر وترتيب ما يظهر على السبورة كلها في مكان واحد.',button(ic('plus',15)+' درس جديد','add-lesson','solid'))+`<div class="lesson-hub"><div class="hub-intro"><span class="eyebrow">تسلسل العمل</span><div class="hub-path"><span>01 <b>اختيار الدرس</b></span><i>›</i><span>02 <b>التحضير</b></span><i>›</i><span>03 <b>الكتاب والوسائل</b></span><i>›</i><span>04 <b>المشاهد</b></span><i>›</i><span>05 <b>العرض</b></span></div></div><div class="hub-lessons"><div class="hub-sectiontitle"><h2>دروسي</h2><p>اختاري درسًا واحدًا لاستكمال جميع تفاصيله</p></div>${state.lessons.map((l,i)=>`<button class="hub-lesson" data-act="lesson:${l.id}"><span class="hub-index">${String(i+1).padStart(2,'0')}</span><span class="hub-lessoncopy"><strong>${esc(l.title)}</strong><small>${esc(l.unit)} · ${esc(l.grade)}</small></span><span class="hub-open">فتح مساحة الدرس ←</span></button>`).join('')||'<p class="muted">أنشئي درسك الأول لبدء التحضير.</p>'}</div><div class="hub-inline"><div><b>الكتب والعروض والفيديوهات</b><p>مكان ثابت للمصادر العامة، مع ربط كل ملف بالدرس المناسب.</p></div>${button('فتح المكتبة','library','softbtn')}</div></div>`}
function lessonDetail(){let l=ensureLessonExtras(state.lessons.find(l=>l.id===lessonId)||state.lessons[0]),p=l.preparation;return header(esc(l.title),'صفحة العمل الرئيسية لهذا الدرس: من التحضير حتى العرض على سبورة الطالبات.',button('رجوع للدروس','lessons','softbtn')+button('فتح شاشة الطالبات','open-projector','solid'))+`<div class="lesson-workbench"><div class="lesson-topline"><span>الصف ${esc(l.grade)} · ${esc(l.unit)}</span><span>${l.scenes.length} مشاهد مرتبة · ${l.resources.length} موارد مرتبطة</span></div><details class="work-step" open><summary><span class="step-no">01</span><span><b>تحضير المعلمة</b><small>الأهداف، التهيئة، الاستراتيجيات، أدوات التقويم والتمايز</small></span><i class="chevron">⌄</i></summary><div class="step-body"><form data-form="lesson-prep" data-id="${esc(l.id)}"><div class="prep-grid"><label>فكرة الدرس<textarea name="description">${esc(l.description)}</textarea></label><label>الأهداف التعليمية<textarea name="objectives">${esc(l.objectives)}</textarea></label><label>المعرفة السابقة<textarea name="prerequisites">${esc(p.prerequisites)}</textarea></label><label>التهيئة والتمهيد<textarea name="introduction">${esc(p.introduction)}</textarea></label><label>استراتيجيات التعلم النشط<textarea name="strategies">${esc(p.strategies)}</textarea></label><label>الوسائل التعليمية<textarea name="materials">${esc(p.materials)}</textarea></label><label>التقويم التكويني والختامي<textarea name="assessment">${esc(p.assessment)}</textarea></label><label>العلاج والإثراء والفروق الفردية<textarea name="differentiation">${esc(p.differentiation)}</textarea></label><label>القيم والربط بالحياة<textarea name="values">${esc(p.values)}</textarea></label><label>الواجب والمتابعة<textarea name="homework">${esc(p.homework)}</textarea></label></div><div class="inline-end"><button class="solid" type="submit">حفظ التحضير</button></div></form></div></details><details class="work-step"><summary><span class="step-no">02</span><span><b>الكتب والوسائل</b><small>ارفعي ملفاتك أو اختاريها من المكتبة وأرفقيها بهذا الدرس</small></span><i class="chevron">⌄</i></summary><div class="step-body"><div class="resource-head"><div><h3>ملفات هذا الدرس</h3><p>يمكنك فتح PDF والصور والفيديو محليًا من المتصفح بعد إضافتها. حفظها على جميع الأجهزة أو تقديمها للطالبات يتطلب خادمًا محميًا.</p></div><button class="softbtn" data-act="lesson-upload" type="button">إضافة ملفات</button><input type="file" id="lessonResourceInput" accept=".pdf,.ppt,.pptx,.mp4,.webm,.png,.jpg,.jpeg,.json,.docx" multiple hidden></div><div class="resource-list">${l.resources.length?l.resources.map(r=>`<div class="resource-line"><span class="file-icon">${ic('file',18)}</span><span><b>${esc(r.name)}</b><small>${esc(r.kind||'ملف')} · محفوظ في هذا المتصفح</small></span>${button('معاينة','view-media:'+r.id,'textbutton')}${button('حذف','remove-resource:'+l.id+':'+r.id,'textbutton')}</div>`).join(''):'<p class="empty">ما أُضيفت ملفات لهذا الدرس بعد.</p>'}</div><div class="inline-end">${button('فتح المكتبة العامة','library','textbutton')}</div></div></details><details class="work-step"><summary><span class="step-no">03</span><span><b>تسلسل مشاهد الحصة</b><small>ابدئي بالترحيب أو قواعد الصف أو أي مشهد تختارينه، ثم رتّبي العرض</small></span><i class="chevron">⌄</i></summary><div class="step-body"><div class="scene-intro"><p>المشهد الأول ليس إلزاميًا. غيّري الترتيب بالأسهم وعدّلي كل مشهد، ولا يظهر شيء على السبورة إلا عندما تضغطين «اعرضي الآن».</p>${button(ic('plus',14)+' إضافة مشهد','add-scene','solid')}</div><div class="scene-list">${l.scenes.map((scene,i)=>`<article class="scene-item"><span class="scene-order">${String(i+1).padStart(2,'0')}</span><div class="scene-copy"><span class="scene-kind">${esc(sceneTypes.find(x=>x[0]===scene.type)?.[1]||'مشهد مخصص')}</span><strong>${esc(scene.title)}</strong><small>${esc(scene.text)}</small></div><div class="scene-buttons"><button class="little-control" data-act="scene-up:${scene.id}" aria-label="نقل للأعلى" title="للأعلى">↑</button><button class="little-control" data-act="scene-down:${scene.id}" aria-label="نقل للأسفل" title="للأسفل">↓</button>${button('تعديل','edit-scene:'+scene.id,'textbutton')}${button('حذف','delete-scene:'+scene.id,'textbutton warntext')}${button('اعرضي الآن','show-scene:'+scene.id,'softbtn')}</div></article>`).join('')}</div></div></details><details class="work-step"><summary><span class="step-no">04</span><span><b>إدارة الحصة والتقييم</b><small>تسجيل الحضور، اختيار طالبة، المؤقت، بنك الأسئلة، ألعاب المجموعات</small></span><i class="chevron">⌄</i></summary><div class="step-body"><div class="lesson-links">${[['attendance','تسجيل الحضور','users'],['random','اختيار عشوائي','target'],['timer','مؤقت النشاط','timer'],['quiz','سؤال سريع','book'],['games','الألعاب التفاعلية','game'],['skills','مختبر المهارات','target']].map(([a,n,i])=>`<button data-act="${a==='games'||a==='skills'?'go:'+a:a}" class="step-tool">${ic(i,19)}${n}</button>`).join('')}</div></div></details><div class="lesson-footer-actions"><div><b>شاشة الطالبات منفصلة</b><p>تبقى هذه المساحة متاحة لك أثناء العرض. استخدمي «توسيع الشاشة» وليس نسخ الشاشة.</p></div>${button('افتحي السبورة','open-projector','solid')}${button('لوحة التحكم بالعرض','studio','softbtn')}</div></div>`}
function studio(){let l=state.lessons.find(x=>x.id===lessonId)||state.lessons[0];return header('التحكم بالعرض','هذه لوحة خاصة بالمعلمة فقط. السبورة تفتح في نافذة مستقلة، ولا تتبع تنقلك داخل الموقع.',button('فتح نافذة الطالبات','open-projector','solid')+button('العودة لمساحة الدرس','lesson:'+l.id,'softbtn'))+`<section class="control-stage"><div class="display-preview"><span class="section-kicker">المشهد الحالي على السبورة</span><h2>${esc(state.board.title)}</h2><p>${esc(state.board.question)}</p><span class="preview-badge">${state.board.blank?'الشاشة معتمة':'الشاشة جاهزة'}</span></div><div class="display-actions"><h3>تحكم سريع</h3>${button('إظهار الحل','board-answer','softbtn')}${button('إخفاء الحل','board-hide','softbtn')}${button('تعتيم فوري','board-blank','softbtn')}${button('استئناف','board-resume','softbtn')}</div></section><details class="work-step" open><summary><span class="step-no">01</span><span><b>المشاهد الجاهزة</b><small>اختاري ما يظهر دون الكشف عن شاشة المعلمة</small></span><i class="chevron">⌄</i></summary><div class="step-body"><div class="scene-picker">${ensureLessonExtras(l).scenes.map((s,i)=>`<button data-act="show-scene:${s.id}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(s.title)}</b></button>`).join('')}</div></div></details><details class="work-step"><summary><span class="step-no">02</span><span><b>سؤال سريع أو نشاط</b><small>اكتبي السؤال والحل عند الحاجة فقط</small></span><i class="chevron">⌄</i></summary><div class="step-body"><div class="prep-grid"><label>عنوان المشهد<input id="boardTitle" value="${esc(state.board.title)}"></label><label>الصف<input id="boardSubtitle" value="${esc(state.board.subtitle)}"></label><label>السؤال<textarea id="boardQuestion">${esc(state.board.question)}</textarea></label><label>الحل<input id="boardAnswer" value="${esc(state.board.answer)}"></label></div><div class="row mt">${button('عرض السؤال','board-question','solid')}${button('إظهار الحل','board-answer','softbtn')}${button('بدء مؤقت','timer','softbtn')}${button('قواعد الصف','classrules','softbtn')}</div></div></details><div class="notice mt">لفتح العرض على البروجكتر: اختاري وضع Extend، انقلي نافذة السبورة فقط للشاشة الثانية. عند منع النوافذ المنبثقة: <a href="projector.html" target="_blank" rel="noopener">افتحي السبورة يدويًا</a>.</div>`}
function assignments(){return header('الواجبات والتقييم','بنك أسئلة منظم، وتصحيح بسيط لتجربة سير العمل.',button('سؤال جديد','add-question','solid')+button('واجب جديد','add-assignment','softbtn'))+`<div class="layout-two"><div class="paper"><h3>بنك الأسئلة</h3>${state.questions.map((q,i)=>`<div class="lesson-row"><span class="number-marker">${i+1}</span><div class="grow"><b>${esc(q.text)}</b><small>${esc(q.skill)} · ${esc(className(q.classId))}</small></div>${button('تعديل','edit-question:'+q.id,'textbutton')}${button('عرض','ask-question:'+q.id,'textbutton')}</div>`).join('')||'<div class="empty">أضيفي أول سؤال</div>'}</div><div class="stack"><div class="paper"><h3>الواجبات</h3>${state.assignments.map(a=>`<div class="shortcut-row"><div><b>${esc(a.title)}</b><div class="muted">${esc(className(a.classId))} · ${esc(a.due||'بدون موعد')}</div></div><span class="tag">${a.published?'منشور (تجريبي)':'مسودة'}</span></div>`).join('')||'<div class="empty">لا توجد واجبات حتى الآن.</div>'}</div><div class="notice">التصحيح هنا للأسئلة ذات الخيار الواحد. تقييم الرياضيات المتقدم والتحقق من الكسور المتكافئة يحتاج محركًا متخصصًا قبل النشر.</div></div></div>`}
function library(){return header('الكتب والملفات','هنا تضيفين مصادر المدرسة العامة، ومن «مساحة الدرس» تربطين الموارد المناسبة بكل درس.',button('إضافة ملفات','add-media','solid'))+`<div class="library-landing"><div class="library-lead"><span class="section-kicker">مكتبة المعلمة</span><h2>كل مصادرك في مكان واضح</h2><p>كتب المنهج، العروض، الفيديوهات، أوراق العمل والصور. اختاري درسًا لإرفاق مواده ضمن تسلسل الحصة.</p><div class="row">${button('إضافة ملف','add-media','solid')}${button('العودة للدروس','lessons','softbtn')}</div></div><div class="library-types">${[['📖','الكتب','PDF'],['▤','العروض','PPTX'],['▶','الفيديوهات','MP4'],['▧','أوراق العمل','PDF / DOCX']].map(([ico,n,ext])=>`<div class="library-type"><span>${ico}</span><b>${n}</b><small>${ext}</small></div>`).join('')}</div></div><div class="paper"><div class="row between mb"><h3>المحتوى المضاف</h3><span class="muted">${state.media.length} ملفات</span></div><input type="file" id="mediaInput" accept=".pdf,.ppt,.pptx,.mp4,.webm,.jpg,.jpeg,.png,.json,.csv,.docx" multiple class="visually-hidden">${state.media.length?state.media.map(m=>`<div class="resource-line"><span class="file-icon">${ic('file',17)}</span><span><b>${esc(m.name)}</b><small>${Math.round(m.size/1024)} KB · محلي في المتصفح</small></span>${button('استعراض','view-media:'+m.id,'textbutton')}</div>`).join(''):'<div class="empty">لا توجد ملفات مضافة بعد. اضغطي «إضافة ملفات» أعلاه.</div>'}<p class="small-print">مهم: تحفظ نسخة الملف في هذا المتصفح فقط عبر IndexedDB إن سمحت مساحة التخزين؛ لا تنتقل لجهاز آخر، ولا تكفي للفيديوهات الضخمة. نشر الكتب والفيديوهات للطالبات يتطلب خادمًا آمنًا.</p></div>`}
function games(){return header('الألعاب والتحفيز','الهدف فهم المهارة أولًا، ثم تأتي المتعة.',button('تصفير الجولة','reset-game','softbtn'))+`<div class="layout-two"><div class="paper"><h3>شدّ الحبل · تحدي الفريقين</h3><div class="activity-strip"><div>فريق الفراشات <b>${gameScore.a}</b></div><span style="font-size:27px">〰</span><div>فريق الغيوم <b>${gameScore.b}</b></div></div><div class="row mt">${button('نقطة للفراشات','game-a','solid')}${button('نقطة للغيوم','game-b','softbtn')}${button('اعرضي النتيجة على السبورة','board-game','softbtn')}</div><h3 class="mt">تحدي الحساب</h3><p class="muted">3 + 4 = ؟</p><div class="row">${['6','7','8'].map((v,i)=>button(v,'math:'+i,'softbtn')).join('')}</div></div><aside class="stack"><div class="paper"><h3>هدية معنوية</h3><p class="muted">رسالة مشجعة بعد الإجابة، بدون مبالغة أو أصوات مفاجئة.</p>${button('افتحي صندوق التشجيع','surprise','solid')}</div><div class="paper"><h3>ألعاب لاحقة</h3><p class="muted">المتاهة، الجسر، البطاقات المتطابقة، مختبر الكسور، متجر الرياضيات، وبطاقات الاكتشاف. هذه تحتاج بناء كل محرك لعب واختباره.</p></div></aside></div>`}
function reports(){let n=state.students.length,p=state.pointsLog.length,a=state.attendance.length;return header('التقارير والشهادات','مؤشرات من البيانات الموجودة فعلًا في هذه النسخة.',button('طباعة ملخص','print','solid')+button('شهادة تشجيع','certificate','softbtn'))+`<div class="page-body"><div class="two-cards"><div class="paper"><h3>نظرة سريعة</h3><div class="history-row">الطالبات المسجلات <b class="grow" style="text-align:left">${n}</b></div><div class="history-row">سجلات حضور <b class="grow" style="text-align:left">${a}</b></div><div class="history-row">مرات إضافة النقاط <b class="grow" style="text-align:left">${p}</b></div></div><div class="paper"><h3>نقاط التشجيع</h3><div class="report-bars">${state.students.slice(0,7).map(s=>`<div class="bar" style="height:${Math.max(8,Math.min(100,s.points||0))}%"><span>${esc(s.name)} · ${s.points||0}</span></div>`).join('')}</div></div></div><div class="paper"><h3>توثيق عمل المعلمة</h3><p class="muted">سجل التحضير، استراتيجيات التعلم النشط، خطط العلاج والإثراء، التواصل مع أولياء الأمور، وتوثيق الإنجازات. لا تُحتسب الأعمال منجزة تلقائيًا لمجرد وجود قالب لها.</p>${button('إضافة ملاحظة توثيق','add-note','softbtn')}</div></div>`}
function parents(){return header('أولياء الأمور','متابعة روابط الأبناء مع تحكم مستقل لكل فصل.',button('إضافة ربط تجريبي','add-parent','solid'))+`<div class="layout-two"><div class="paper"><h3>الحسابات المرتبطة</h3>${state.parents.map(p=>`<div class="shortcut-row"><div><b>${esc(p.name)}</b><p class="muted">${esc(state.students.find(s=>s.id===p.studentId)?.name||'غير مرتبط')}</p></div><span class="tag">تجريبي · بدون تحقق</span></div>`).join('')}</div><div class="paper"><h3>طلب الانضمام حسب الفصل</h3>${state.classes.map(c=>`<div class="shortcut-row"><b>${esc(c.name)}</b><select data-enrollment="${esc(c.id)}"><option value="review" ${state.enrollment[c.id]==='review'?'selected':''}>مراجعة المعلمة</option><option value="auto" ${state.enrollment[c.id]==='auto'?'selected':''}>قبول آلي بعد تحقق موثوق</option><option value="team" ${state.enrollment[c.id]==='team'?'selected':''}>الفريق فقط</option><option value="closed" ${state.enrollment[c.id]==='closed'?'selected':''}>مغلق</option></select></div>`).join('')}<p class="small-print">هذه تفضيلات واجهة فقط. لا يوجد في النموذج نظام تحقق أرقام أو QR آمن، لذلك لا يُتاح دخول فعلي بهذه الخيارات.</p></div></div>`}
function tools(){return header('أدوات المعلمة','كل شيء له وظيفة واضحة بدون ازدحام بصري.')+`<div class="tools-grid">${[['calculator','حاسبة سريعة','target'],['random','سحب اسم حاضر','users'],['timer','مؤقت نشاط','timer'],['calendar','التقويم','calendar'],['export','نسخة احتياطية','download'],['import','استيراد بيانات','upload'],['prompt','استوديو البرومبت','wand'],['certificate','شهادة لطالبة','heart'],['settings','تخصيص الرئيسية','settings']].map(([a,n,i])=>`<button class="tool-tile" data-act="${a}">${ic(i)}<b>${n}</b><small>فتح الأداة</small></button>`).join('')}</div><input id="importJSON" type="file" accept=".json" hidden>`}
function tasks(){return header('مهامي اليومية','مستوحاة من آلية ملفك: تثبيت، أولوية، إنجاز وروتين يتجدد يوميًا.',button(ic('plus',14)+' إضافة مهمة','add-task','solid'))+`<div class="paper"><div class="segmented mb">${[['all','كل المهام'],['daily','اليومية'],['routine','الروتين'],['weekly','الأسبوعية'],['done','المنجزة']].map(([k,v])=>`<button class="${taskTab===k?'selected':''}" data-tasktab="${k}">${v}</button>`).join('')}</div>${taskList(0,taskTab)}<p class="small-print mt">ملاحظة: الروتين يحتفظ بالمهمة، ويتجدد إنجازها مع بداية يوم جديد.</p></div>`}
function calendar(){return header('التقويم الدراسي','المواعيد كلها تحت تحكم المعلمة، وليس فيه تواريخ رسمية مفترضة.',button('إضافة مناسبة','add-event','solid'))+`<div class="layout-two"><div class="paper"><h3>هذا الشهر</h3><div class="mini-calendar">${dateCalendar()}</div></div><div class="paper"><h3>المواعيد المسجلة</h3>${[...state.events].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="shortcut-row"><div><b>${esc(e.title)}</b><small> · ${esc(e.date)}</small></div>${button('حذف','delete-event:'+e.id,'textbutton warntext')}</div>`).join('')||'<div class="empty">التقويم فارغ، أضيفي المناسبات الفعلية حسب المدرسة.</div>'}</div></div>`}
function alerts(){return header('التنبيهات','رسائل وملاحظات داخل مساحة المعلمة.',button('تنبيه جديد','add-alert','solid'))+`<div class="paper">${state.alerts.map(a=>`<div class="shortcut-row"><div>${ic('bell',16)} ${esc(a.text)}</div>${button('حذف','delete-alert:'+a.id,'textbutton warntext')}</div>`).join('')}</div>`}
function studentPortal(){let s=state.students[0];return `<div class="workspace" style="max-width:1160px"><div class="topline"><div class="row"><div class="logo-mark" style="height:37px;width:37px">م</div><strong>مساحة الصغيرة</strong></div><a class="softbtn" href="skills.html?mode=student">مختبر المهارات</a>${button('رجوع للمعلمة','teacher-portal','softbtn')}</div><section class="student-scene kid-hero"><div><span class="pill" style="background:#fff">رحلة الرياضيات</span><h1>أهلًا يا ${esc(s?.name||'بطلتنا')}!<br>جاهزة نكتشف شيئًا جديدًا؟</h1><p>كل محاولة تقرّبنا لفكرة أجمل.</p></div><svg class="kid-art" viewBox="0 0 200 185" aria-hidden="true"><ellipse cx="103" cy="166" rx="83" ry="13" fill="#e3ede5"/><path d="M64 122q-19-57 24-72t65 19q14 38-12 77H73z" fill="#b3d3c7"/><rect x="76" y="69" width="54" height="59" rx="17" fill="#e8b99c"/><path d="M70 77q-11-37 18-45 38-11 51 29l-9 7q-13-21-38-14z" fill="#6f8790"/><circle cx="95" cy="94" r="3" fill="#526b70"/><circle cx="118" cy="94" r="3" fill="#526b70"/><path d="M97 111q9 10 20 0" stroke="#a36f6e" stroke-width="3" fill="none" stroke-linecap="round"/><path d="M63 130q37-24 86 0l12 38H52z" fill="#91b6c6"/><path d="M28 86l15-19 17 19-17 19z" fill="#eadca2"/><path d="M156 42l9-14 8 14-8 14z" fill="#a9d2d4"/><circle cx="169" cy="108" r="10" fill="#d8d2ea"/></svg></section><section class="mt"><h2 class="kid-title">اختاري مغامرتك اليوم</h2><div class="kid-options"><button class="kid-action" data-act="student-quiz">${ic('target')} تحدي صغير في الرياضيات <small>سؤال بسيط</small></button><button class="kid-action" data-act="student-help">${ic('heart')} ما فهمت الفكرة <small>نشرحها خطوة خطوة</small></button><button class="kid-action" data-act="student-book">${ic('book')} كتابي ودفتري <small>نتعلم ونجرّب</small></button></div></section><section class="mt paper"><div class="row between"><div><h3 style="margin:0">شارات الاجتهاد</h3><p class="muted">التشجيع على المحاولة، مو السرعة فقط.</p></div><div class="number-marker">${s?.points||0}</div></div></section><div id="kidContent" class="mt"></div><footer class="small-print mt">معاينة لطالبة واحدة ببيانات تجريبية. لا يوجد تسجيل دخول آمن بعد.</footer></div>`}
function parentPortal(){let p=state.parents[0],s=state.students.find(s=>s.id===p?.studentId);return `<div class="workspace" style="max-width:1020px"><div class="topline"><b>مساحة الأسرة</b>${button('رجوع للمعلمة','teacher-portal','softbtn')}</div>${header('أهلًا بأهل '+esc(s?.name||'الطالبة'),'هنا تظهر متابعة الابنة المرتبطة فقط، عندما تتوفر حسابات وصلاحيات حقيقية.') }<div class="layout-two"><div class="paper"><h3>${esc(s?.name||'الطالبة')} · نظرة هادئة</h3><div class="history-row">نقاط الاجتهاد <strong class="grow" style="text-align:left">${s?.points||0}</strong></div><div class="history-row">الفصل <strong class="grow" style="text-align:left">${esc(className(s?.classId))}</strong></div><div class="history-row">آخر الحضور <span class="grow" style="text-align:left">${esc(state.attendance.filter(a=>a.studentId===s?.id).at(-1)?.date||'لم يُسجّل')}</span></div></div><div class="paper"><h3>رسالة للمنزل</h3><p class="muted">المهارات التي تحسّنت، الواجبات، والملاحظات الإيجابية تظهر هنا بعد نشرها من المعلمة. لا تظهر أي بيانات لطالبات أخريات.</p></div></div><p class="small-print mt">هذه معاينة فقط وليست بوابة دخول مصادقًا عليها.</p></div>`}
function render(){document.body.classList.toggle('dark',state.dark&&role==='teacher');let content=page==='home'?home():page==='schedule'?schedule():page==='classes'?classes():page==='lessons'?lessons():page==='lesson-detail'?lessonDetail():page==='studio'?studio():page==='assignments'?assignments():page==='library'?library():page==='games'?games():page==='reports'?reports():page==='parents'?parents():page==='tools'?tools():page==='tasks'?tasks():page==='calendar'?calendar():page==='alerts'?alerts():home();$('#app').innerHTML=role==='student'?studentPortal():role==='parent'?parentPortal():layout(content)}
function go(p){if(p==='skills'){window.location.href='skills.html';return}role='teacher';page=p;render();window.scrollTo({top:0,behavior:'smooth'})}function notifyBoard(){setBoard({title:$('#boardTitle')?.value||state.board.title,subtitle:$('#boardSubtitle')?.value||state.board.subtitle,question:$('#boardQuestion')?.value||state.board.question,answer:$('#boardAnswer')?.value||state.board.answer})}
function modal(title,body){document.querySelector('.modal-layer')?.remove();let el=document.createElement('div');el.className='modal-layer';el.id='modalLayer';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true"><div class="row between mb"><h2>${title}</h2><button class="close" data-act="close-modal" aria-label="إغلاق">×</button></div>${body}</section>`;document.body.append(el)}function close(){document.querySelector('.modal-layer')?.remove()}function field(label,name,value='',type='text',attrs=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}function formBtn(text='حفظ'){return `<div class="row mt"><button class="solid" type="submit">${text}</button>${button('إلغاء','close-modal','softbtn')}</div>`}
function openTask(entry){let t=entry||{title:'',type:'daily',priority:1,date:'',pinned:false,note:''};modal(entry?'تعديل المهمة':'مهمة جديدة',`<form data-form="task" data-id="${esc(entry?.id||'')}"><div class="stack">${field('عنوان المهمة','title',t.title,'text','required maxlength="160"')}<div class="form-grid"><div class="field"><label>التصنيف</label><select name="type">${[['daily','يومية'],['routine','روتين يتجدد كل يوم'],['weekly','أسبوعية']].map(([v,n])=>`<option value="${v}" ${v===t.type?'selected':''}>${n}</option>`).join('')}</select></div>${field('الموعد (اختياري)','date',t.date||'','date')}</div><div class="form-grid"><div class="field"><label>الأولوية</label><select name="priority">${[1,2,3].map(n=>`<option value="${n}" ${n===t.priority?'selected':''}>${'!'.repeat(n)}</option>`).join('')}</select></div><div class="field"><label>تثبيت في الأعلى</label><select name="pinned"><option value="0">لا</option><option value="1" ${t.pinned?'selected':''}>نعم</option></select></div></div><div class="field"><label>ملاحظة</label><textarea name="note">${esc(t.note||'')}</textarea></div>${formBtn()}</div></form>${entry?button('حذف المهمة','delete-task:'+entry.id,'textbutton warntext mt'):''}`)}
function scheduleForm(entry){let t=entry||{title:'الرياضيات',topic:'',classId:state.classes[0]?.id,day:new Date().getDay(),start:'07:30',end:'08:15'};modal(entry?'تعديل الحصة':'إضافة حصة',`<form data-form="schedule" data-id="${esc(entry?.id||'')}"><div class="stack">${field('اسم المادة','title',t.title,'text','required')}${field('عنوان الدرس','topic',t.topic)}<div class="form-grid"><div class="field"><label>الفصل</label><select name="classId">${state.classes.map(c=>`<option value="${c.id}" ${c.id===t.classId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>اليوم</label><select name="day">${days.map((d,i)=>`<option value="${i}" ${i===t.day?'selected':''}>${d}</option>`).join('')}</select></div></div><div class="form-grid">${field('البداية','start',t.start,'time','required')}${field('النهاية','end',t.end,'time','required')}</div>${formBtn()}</div></form>`)}
function studentForm(entry){let s=entry||{name:'',classId};modal(entry?'بيانات الطالبة':'إضافة طالبة',`<form data-form="student" data-id="${esc(entry?.id||'')}"><div class="stack">${field('اسم الطالبة','name',s.name,'text','required maxlength="90"')}<div class="field"><label>الفصل</label><select name="classId">${state.classes.map(c=>`<option value="${c.id}" ${c.id===s.classId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>${formBtn()}</div></form>`)}
async function showMedia(fileId){try{let file=await window.MasahaFiles?.get(fileId);if(!file){toast('هذا الملف غير متاح في هذا المتصفح؛ أعيدي إضافته');return}let url=URL.createObjectURL(file),name=esc(file.name||'الملف'),kind=file.type||'',content=kind.includes('pdf')?`<iframe style="width:100%;height:65vh;border:0" src="${url}" title="${name}"></iframe>`:kind.startsWith('image/')?`<img src="${url}" alt="${name}" style="max-width:100%;max-height:65vh;object-fit:contain">`:kind.startsWith('video/')?`<video controls playsinline style="width:100%;max-height:65vh" src="${url}"></video>`:`<p>المتصفح لا يدعم معاينة هذا النوع مباشرة. حمّلي الملف لفتحه في التطبيق المناسب.</p><a href="${url}" download="${name}" class="solid">حفظ الملف</a>`;modal(name,content)}catch{toast('تعذرت معاينة الملف؛ قد يكون تخزين المتصفح غير متاح')}}
async function saveChosenFiles(files,scope){let l=scope==='lesson'?ensureLessonExtras(state.lessons.find(x=>x.id===lessonId)):null;let ok=0;for(let file of files){let fileId=id();try{await window.MasahaFiles.put(fileId,file);let item={id:fileId,name:file.name,kind:file.type||file.name.split('.').pop(),mime:file.type,size:file.size};if(l)l.resources.push(item);else state.media.push(item);ok++}catch{toast('لم تكفِ مساحة المتصفح لحفظ بعض الملفات')}}persist();render();if(ok)toast('حُفظ '+ok+' ملفًا في هذا المتصفح')} 
function editScene(scene){let v=scene||{title:'',type:'custom',text:'',answer:''};modal(scene?'تحرير مشهد الحصة':'مشهد جديد',`<form data-form="scene" data-id="${esc(scene?.id||'')}" class="stack"><div class="field"><label>نوع المشهد</label><select name="type">${sceneTypes.map(([k,n])=>`<option value="${k}" ${v.type===k?'selected':''}>${n}</option>`).join('')}</select></div>${field('عنوان المشهد','title',v.title,'text','required maxlength="100"')}<div class="field"><label>النص الذي تشاهده الطالبات</label><textarea name="text">${esc(v.text)}</textarea></div>${field('الإجابة إن وجدت','answer',v.answer||'')}${formBtn()}</form>`)}
function lessonForm(entry){let l=entry||{title:'',grade:'الخامس',unit:'',description:'',objectives:''};modal(entry?'تحرير درس':'درس جديد',`<form data-form="lesson" data-id="${esc(entry?.id||'')}"><div class="stack">${field('عنوان الدرس','title',l.title,'text','required')}<div class="form-grid">${field('الصف','grade',l.grade)}${field('الوحدة','unit',l.unit)}</div><div class="field"><label>وصف فكرة الدرس</label><textarea name="description">${esc(l.description)}</textarea></div><div class="field"><label>الأهداف التعليمية</label><textarea name="objectives">${esc(l.objectives)}</textarea></div>${formBtn()}</div></form>`)}
function questionForm(entry){let q=entry||{text:'',options:['','',''],correct:0,skill:'',classId};modal(entry?'تعديل سؤال':'سؤال جديد',`<form data-form="question" data-id="${esc(entry?.id||'')}"><div class="stack">${field('نص السؤال','text',q.text,'text','required')}<div class="form-grid">${field('خيار 1','o0',q.options[0]||'','text','required')}${field('خيار 2','o1',q.options[1]||'','text','required')}${field('خيار 3','o2',q.options[2]||'','text','required')}<div class="field"><label>الإجابة الصحيحة</label><select name="correct">${[0,1,2].map(n=>`<option value="${n}" ${n===q.correct?'selected':''}>الخيار ${n+1}</option>`).join('')}</select></div></div>${field('المهارة','skill',q.skill)}<div class="field"><label>الفصل</label><select name="classId">${state.classes.map(c=>`<option value="${c.id}" ${c.id===q.classId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>${formBtn()}</div></form>`)}
function settings(){document.querySelector('.shade')?.remove();document.querySelector('.settings-drawer')?.remove();let shade=document.createElement('div');shade.className='shade';shade.dataset.act='close-settings';let panel=document.createElement('section');panel.className='settings-drawer';panel.innerHTML=`<div class="row between mb"><h2>إعدادات مساحتك</h2><button class="close" data-act="close-settings">×</button></div><form data-form="settings"><div class="stack">${field('اسم المعلمة','teacher',state.teacher)}${field('اسم المدرسة','school',state.school)}${field('العام الدراسي','year',state.year)}${field('الفصل الدراسي','term',state.term)}<div class="field"><label>عبارة الترحيب</label><textarea name="phrase">${esc(state.phrase)}</textarea></div><h3>ما يظهر في الرئيسية</h3>${[['timeline','مسار الحصص'],['tasks','المهام والروتين'],['notices','التنبيهات'],['tools','الاختصارات السريعة']].map(([k,v])=>`<label class="switchline"><input type="checkbox" name="show_${k}" ${state.show[k]?'checked':''}><span>${v}</span></label>`).join('')}<label class="switchline"><input type="checkbox" name="dark" ${state.dark?'checked':''}><span>الوضع الداكن للمعلمة</span></label>${formBtn('حفظ الإعدادات')}</div></form><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><div class="row">${button('تصدير JSON','export','softbtn')}${button('استيراد JSON','import','softbtn')}</div><input id="importJSON" type="file" accept=".json" hidden><p class="small-print">الحفظ الحالي في هذا المتصفح فقط. لا تضعي بيانات حقيقية حساسة قبل تجهيز الخادم والحماية.</p>`;document.body.append(shade,panel)}function closeSettings(){document.querySelector('.shade')?.remove();document.querySelector('.settings-drawer')?.remove()}
function attendance(){let ss=state.students.filter(s=>s.classId===classId);modal('كشف حضور · '+esc(className(classId)),`<form data-form="attendance" data-class="${esc(classId)}"><p class="notice">ابدئي بدون رصد، ثم حددي الحاضرات والغائبات واحفظي. لا يُفترض حضور أي طالبة تلقائيًا.</p>${ss.map(s=>{let a=state.attendance.find(a=>a.studentId===s.id&&a.date===iso());return `<div class="shortcut-row"><b>${esc(s.name)}</b><select name="a_${esc(s.id)}" required><option value="">لم يُرصد</option><option value="1" ${a?.present===true?'selected':''}>حاضرة</option><option value="0" ${a?.present===false?'selected':''}>غائبة</option></select></div>`}).join('')||'<p>لا توجد طالبات</p>'}${formBtn('اعتماد الحضور')}</form>`)}
function randomPicker(){let ss=state.students.filter(s=>s.classId===classId&&!state.attendance.some(a=>a.studentId===s.id&&a.date===iso()&&!a.present));let chosen=ss.length?ss[Math.floor(Math.random()*ss.length)]:null;modal('اختيار عشوائي',`<div class="student-scene" style="text-align:center"><div style="font-size:55px;margin:8px">☁</div><h2 style="font-size:31px">${esc(chosen?.name||'لا توجد طالبة متاحة')}</h2><p class="muted">${chosen?'اخترنا اسمًا من الطالبات غير المسجلات غائبات.':'تأكدي من الفصل والكشف.'}</p>${button('اختيار جديد','random','solid')}</div>`)}
function certificate(){modal('شهادة تشجيع',`<form data-form="certificate"><div class="stack"><div class="field"><label>الطالبة</label><select name="studentId">${state.students.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div>${field('سبب التكريم','reason','اجتهادك الجميل في الرياضيات')}${formBtn('معاينة الشهادة')}</div></form>`)}
function kidAnswer(){let q=state.questions[questionIndex%Math.max(state.questions.length,1)];return q?`<div class="student-scene quiz-box"><span class="pill">تحدي صغير</span><h2 class="kid-title">فكّري واختاري الإجابة</h2><div class="math-question" style="direction:rtl;font-size:36px">${esc(q.text)}</div><div class="answer-options">${q.options.map((o,i)=>`<button data-kid-answer="${i}">${esc(o)}</button>`).join('')}</div><div id="answerFeedback" class="mt"></div></div>`:'<div class="empty">لا توجد أسئلة بعد.</div>'}
function submit(f){let fd=new FormData(f),type=f.dataset.form,ref=f.dataset.id||'',value=n=>String(fd.get(n)||'').trim();
if(type==='lesson-prep'){let l=ensureLessonExtras(state.lessons.find(l=>l.id===ref));l.description=value('description');l.objectives=value('objectives');Object.keys(l.preparation).forEach(k=>l.preparation[k]=value(k));persist();toast('حُفظ التحضير');return}
if(type==='scene'){let l=ensureLessonExtras(state.lessons.find(l=>l.id===lessonId)),e=l.scenes.find(x=>x.id===ref),v={id:e?.id||id(),title:value('title'),type:value('type'),text:value('text'),answer:value('answer')};if(e)Object.assign(e,v);else l.scenes.push(v);persist();close();render();toast('حُفظ المشهد');return}
if(type==='settings'){state.teacher=value('teacher')||'المعلمة';state.school=value('school');state.year=value('year');state.term=value('term');state.phrase=value('phrase');state.dark=fd.has('dark');Object.keys(state.show).forEach(k=>state.show[k]=fd.has('show_'+k));closeSettings();persist();render();toast('حُفظت تفضيلات الرئيسية');return}
if(type==='task'){let t=state.tasks.find(x=>x.id===ref),next={...(t||{}),id:t?.id||id(),title:value('title'),type:value('type'),date:value('date'),priority:Number(value('priority'))||1,pinned:value('pinned')==='1',note:value('note'),done:t?.done||false,doneOn:t?.doneOn||''};if(t)Object.assign(t,next);else state.tasks.push(next)}
if(type==='schedule'){let t=state.schedule.find(x=>x.id===ref),next={id:t?.id||id(),title:value('title'),topic:value('topic'),classId:value('classId'),day:Number(value('day')),start:value('start'),end:value('end')};if(mins(next.end)<=mins(next.start)){toast('يجب أن تكون النهاية بعد البداية');return}if(t)Object.assign(t,next);else state.schedule.push(next)}
if(type==='student'){let s=state.students.find(x=>x.id===ref),next={id:s?.id||id(),name:value('name'),classId:value('classId'),points:s?.points||0};if(s)Object.assign(s,next);else state.students.push(next)}
if(type==='class')state.classes.push({id:id(),name:value('name'),grade:value('grade'),room:value('room')});
if(type==='lesson'){let x=state.lessons.find(x=>x.id===ref),next={id:x?.id||id(),title:value('title'),grade:value('grade'),unit:value('unit'),description:value('description'),objectives:value('objectives')};if(x)Object.assign(x,next);else state.lessons.push(next)}
if(type==='question'){let x=state.questions.find(x=>x.id===ref),next={id:x?.id||id(),text:value('text'),options:[value('o0'),value('o1'),value('o2')],correct:Number(value('correct')),skill:value('skill'),classId:value('classId')};if(x)Object.assign(x,next);else state.questions.push(next)}
if(type==='assignment')state.assignments.push({id:id(),title:value('title'),classId:value('classId'),due:value('due'),published:fd.has('published')});
if(type==='event')state.events.push({id:id(),title:value('title'),date:value('date')});if(type==='alert')state.alerts.push({id:id(),text:value('text'),date:value('date')});if(type==='note')state.teacherNotes.push({id:id(),text:value('text'),date:iso()});if(type==='parent')state.parents.push({id:id(),name:value('name'),studentId:value('studentId'),mode:'review'});
if(type==='attendance'){let ss=state.students.filter(s=>s.classId===f.dataset.class);if(ss.some(s=>value('a_'+s.id)==='')){toast('حددي حالة كل طالبة قبل الاعتماد');return}for(let s of ss){state.attendance=state.attendance.filter(a=>!(a.studentId===s.id&&a.date===iso()));state.attendance.push({id:id(),studentId:s.id,date:iso(),present:value('a_'+s.id)==='1'})}}
if(type==='certificate'){let s=state.students.find(s=>s.id===value('studentId'));const win=window.open('','_blank');if(!win){toast('اسمحي بالنوافذ المنبثقة لمعاينة الشهادة');return}win.document.write(`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>شهادة تشجيع</title><style>body{font-family:Tahoma;text-align:center;margin:8vh;border:12px double #b5d7df;padding:12vh 4vw;color:#3a607e}h1{font-size:48px}h2{font-size:36px}p{font-size:24px}</style><h1>شهادة شكر وتشجيع</h1><p>تُمنح بكل محبة للطالبة</p><h2>${esc(s?.name)}</h2><p>${esc(value('reason'))}</p><p>معلمتك: ${esc(state.teacher)}</p><button onclick="print()">طباعة / حفظ PDF</button></html>`);win.document.close();close();return}
close();persist();render();toast('تم الحفظ')}
// Keep teacher workspace in its original tab/window. The projector is a separate top-level window.
let projectorWindow = null;
function boardWindow(){
  const address = new URL('projector.html', window.location.href).href;
  try {
    if(projectorWindow && !projectorWindow.closed){
      projectorWindow.focus();
      toast('السبورة مفتوحة بالفعل في نافذة مستقلة');
      return;
    }
    projectorWindow = window.open(address, 'masaha_student_projector', 'popup=yes,width=1280,height=800,resizable=yes,scrollbars=yes');
    if(!projectorWindow){
      modal('فتح شاشة الطالبات', `<p>المتصفح منع النافذة الجديدة. اسمحي بالنوافذ المنبثقة أو افتحي شاشة السبورة من الرابط التالي؛ لوحة المعلمة ستبقى مفتوحة.</p><a class="solid" href="projector.html" target="_blank" rel="noopener">فتح السبورة في تبويب مستقل</a>`);
      return;
    }
    toast('فتحت السبورة منفصلة؛ انقلي نافذتها إلى شاشة العرض مع تفعيل توسيع الشاشة');
  }catch(err){
    modal('فتح شاشة الطالبات', '<p>تعذر فتح نافذة السبورة تلقائيًا. افتحي الرابط في تبويب آخر، ولا تغلقي لوحة المعلمة.</p><a class="solid" href="projector.html" target="_blank" rel="noopener">فتح السبورة مستقلّة</a>');
  }
}
function handle(action){
if(action.startsWith('view-media:')){const fileId=action.slice(11);showMedia(fileId);return}
if(action.startsWith('delete-scene:')){let l=ensureLessonExtras(state.lessons.find(x=>x.id===lessonId));if(l.scenes.length<=1){toast('احتفظي بمشهد واحد على الأقل');return}if(confirm('حذف المشهد من تسلسل الحصة؟')){l.scenes=l.scenes.filter(x=>x.id!==action.slice(13));persist();render()}return}
if(action==='lesson-upload'){document.querySelector('#lessonResourceInput')?.click();return}
if(action==='add-scene')return editScene();
if(action.startsWith('edit-scene:')){let l=ensureLessonExtras(state.lessons.find(l=>l.id===lessonId));return editScene(l.scenes.find(x=>x.id===action.slice(11)))}
if(action.startsWith('scene-up:')||action.startsWith('scene-down:')){let l=ensureLessonExtras(state.lessons.find(l=>l.id===lessonId)),sid=action.slice(action.indexOf(':')+1),i=l.scenes.findIndex(x=>x.id===sid),j=i+(action.startsWith('scene-up:')?-1:1);if(i>=0&&j>=0&&j<l.scenes.length){[l.scenes[i],l.scenes[j]]=[l.scenes[j],l.scenes[i]];persist();render()}return}
if(action.startsWith('show-scene:')){let l=ensureLessonExtras(state.lessons.find(l=>l.id===lessonId)||state.lessons[0]),sc=l.scenes.find(x=>x.id===action.slice(11));if(sc){setBoard({screen:'scene',title:sc.title,subtitle:'الصف '+l.grade,question:sc.text,answer:sc.answer||'',reveal:false,blank:false});toast('ظهر المشهد على السبورة')}return}
if(action.startsWith('remove-resource:')){let [,lid,rid]=action.split(':'),l=ensureLessonExtras(state.lessons.find(x=>x.id===lid));l.resources=l.resources.filter(x=>x.id!==rid);window.MasahaFiles?.remove(rid).catch(()=>{});persist();render();return}
if(action.startsWith('go:'))return go(action.slice(3));if(action==='close-modal')return close();if(action==='close-settings')return closeSettings();if(action==='menu')return $('#rail')?.classList.toggle('open');if(action==='settings')return settings();if(action==='student-portal'){role='student';render();return}if(action==='parent-portal'){role='parent';render();return}if(action==='teacher-portal'){role='teacher';page='home';render();return}if(['tasks','calendar','alerts','schedule','studio','lessons','classes','assignments','library','games','reports','parents','tools','skills'].includes(action))return go(action);if(action==='toggle-hometasks'){let el=$('#homeTasks');el.hidden=!el.hidden;$('#taskArrow').textContent=el.hidden?'‹':'⌄';return}
if(action==='add-task')return openTask();if(action.startsWith('delete-task:')){if(confirm('حذف المهمة؟')){state.tasks=state.tasks.filter(t=>t.id!==action.slice(12));persist();close();render()}return}
if(action==='add-schedule')return scheduleForm();if(action.startsWith('edit-schedule:'))return scheduleForm(state.schedule.find(s=>s.id===action.slice(14)));if(action.startsWith('delete-schedule:')){if(confirm('حذف الحصة؟')){state.schedule=state.schedule.filter(x=>x.id!==action.slice(16));persist();render()}return}
if(action==='add-class')return modal('فصل جديد',`<form data-form="class" class="stack">${field('اسم الفصل','name','','text','required')}${field('الصف','grade')}${field('الشعبة','room')}${formBtn()}</form>`);if(action==='add-student')return studentForm();if(action.startsWith('edit-student:'))return studentForm(state.students.find(s=>s.id===action.slice(13)));if(action.startsWith('point:')){let s=state.students.find(s=>s.id===action.slice(6));if(s){s.points++;state.pointsLog.push({studentId:s.id,date:iso(),points:1});persist();render();toast('نقطة تشجيع لـ '+s.name)}return}if(action==='attendance')return attendance();if(action.startsWith('groups:')){let n=+action.slice(7),ss=state.students.filter(s=>s.classId===classId),gr=Array.from({length:n},()=>[]);ss.forEach((s,i)=>gr[i%n].push(s.name));let html=gr.map((a,i)=>`<div class="shortcut-row"><b>الفريق ${i+1}</b><span>${esc(a.join('، '))||'فارغ'}</span></div>`).join('');if($('#groupsResult'))$('#groupsResult').innerHTML=html;else modal('تقسيم المجموعات',html);return}if(action==='random')return randomPicker();
if(action==='add-lesson')return lessonForm();if(action.startsWith('edit-lesson:'))return lessonForm(state.lessons.find(l=>l.id===action.slice(12)));if(action.startsWith('lesson:')){lessonId=action.slice(7);return go('lesson-detail')}if(action.startsWith('send-lesson:')){let l=state.lessons.find(l=>l.id===action.slice(12));setBoard({title:l.title,question:l.description,answer:'',reveal:false,blank:false,screen:'question'});toast('أُرسل المحتوى للسبورة');return}if(action==='open-projector')return boardWindow();if(action==='board-question'){notifyBoard();setBoard({reveal:false,blank:false,screen:'question'});toast('يظهر السؤال على السبورة');return}if(action==='board-answer'){notifyBoard();setBoard({reveal:true,blank:false,screen:'question'});return}if(action==='board-hide'){setBoard({reveal:false});return}if(action==='board-blank'){setBoard({blank:true});return}if(action==='board-resume'){setBoard({blank:false});return}if(action==='board-welcome'){setBoard({blank:false,screen:'welcome',reveal:false});return}if(action==='board-game'){setBoard({blank:false,screen:'game',scoreA:gameScore.a,scoreB:gameScore.b});toast('ظهر التحدي على السبورة');return}if(action==='classrules'){setBoard({blank:false,screen:'rules'});return}if(action==='timer')return modal('مؤقت النشاط',`<p>اختاري مدة المؤقت؛ سيظهر على السبورة مستقلة.</p><div class="row">${[1,3,5,10].map(n=>button(n+' دقائق','set-timer:'+n,'softbtn')).join('')}</div>`);if(action.startsWith('set-timer:')){setBoard({screen:'timer',blank:false,timerEnd:Date.now()+Number(action.slice(10))*60000});close();toast('بدأ مؤقت السبورة');return}
if(action==='add-question')return questionForm();if(action.startsWith('edit-question:'))return questionForm(state.questions.find(q=>q.id===action.slice(14)));if(action.startsWith('ask-question:')){let q=state.questions.find(q=>q.id===action.slice(13));if(q){setBoard({screen:'question',blank:false,title:q.skill||'سؤال رياضيات',question:q.text,answer:q.options[q.correct],reveal:false});toast('أُرسل السؤال إلى السبورة')}return}if(action==='quiz'){let q=state.questions[0];if(q)setBoard({screen:'question',blank:false,title:q.skill,question:q.text,answer:q.options[q.correct],reveal:false});return}if(action==='add-assignment')return modal('واجب جديد',`<form data-form="assignment" class="stack">${field('عنوان الواجب','title','','text','required')}<div class="field"><label>الفصل</label><select name="classId">${state.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div>${field('آخر موعد','due','','date')}<label class="switchline"><input type="checkbox" name="published"> نشر (للمعاينة التجريبية فقط)</label>${formBtn()}</form>`);
if(action==='add-media')return $('#mediaInput')?.click();if(action==='game-a'||action==='game-b'){gameScore[action==='game-a'?'a':'b']++;render();return}if(action==='reset-game'){gameScore={a:0,b:0};render();return}if(action.startsWith('math:'))return toast(action.endsWith('1')?'رائع! إجابة صحيحة':'جرّبي مرة ثانية');if(action==='surprise')return modal('صندوق التشجيع',`<div class="student-scene quiz-box"><div style="font-size:62px">🎁</div><h2>يا لك من مجتهدة!</h2><p>خطوة جديدة في طريق الإبداع. أحسنتِ المحاولة!</p></div>`);
if(action==='add-event')return modal('مناسبة جديدة',`<form data-form="event" class="stack">${field('اسم المناسبة','title','','text','required')}${field('التاريخ','date',iso(),'date','required')}${formBtn()}</form>`);if(action.startsWith('delete-event:')){state.events=state.events.filter(e=>e.id!==action.slice(13));persist();render();return}if(action==='add-alert')return modal('تنبيه جديد',`<form data-form="alert" class="stack">${field('نص التنبيه','text','','text','required')}${field('التاريخ','date',iso(),'date')}${formBtn()}</form>`);if(action.startsWith('delete-alert:')){state.alerts=state.alerts.filter(a=>a.id!==action.slice(13));persist();render();return}
if(action==='add-note')return modal('تدوين فكرة',`<form data-form="note" class="stack"><div class="field"><label>الفكرة أو الملاحظة</label><textarea name="text" required></textarea></div>${formBtn()}</form>`);if(action==='add-parent')return modal('ربط ولي أمر — تجريبي',`<form data-form="parent" class="stack">${field('اسم ولي الأمر','name','','text','required')}<div class="field"><label>الطالبة</label><select name="studentId">${state.students.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><p class="small-print">لا تُعد هذه العملية تحققًا من هوية ولي الأمر.</p>${formBtn()}</form>`);
if(action==='certificate')return certificate();if(action==='print')return window.print();if(action==='calculator')return modal('حاسبة سريعة',`<div class="stack">${field('العدد الأول','numA','','number')}${field('العدد الثاني','numB','','number')}<div class="row">${['+','-','×','÷'].map(x=>button(x,'calc:'+x,'softbtn')).join('')}</div><div id="calcResult" class="notice">النتيجة</div></div>`);if(action.startsWith('calc:')){let a=Number($('#numA')?.value),b=Number($('#numB')?.value),op=action.slice(5);$('#calcResult').textContent=op==='+'?a+b:op==='-'?a-b:op==='×'?a*b:b===0?'القسمة على صفر غير ممكنة':a/b;return}if(action==='prompt')return modal('استوديو البرومبت',`<p class="muted">اكتبي وصف الدرس ثم انسخي نص التوجيه إلى المساعد الذي تختارينه. لا توجد مشاركة آلية للملفات أو للمحادثات.</p><textarea id="promptTopic" class="editor" placeholder="الدرس والصف والمخرجات المطلوبة"></textarea><div class="row mt">${button('نسخ توجيه جاهز','copy-prompt','solid')}<a class="softbtn" href="https://claude.ai" target="_blank" rel="noopener noreferrer">فتح Claude</a><a class="softbtn" href="https://chatgpt.com" target="_blank" rel="noopener noreferrer">فتح ChatGPT</a></div>`);if(action==='copy-prompt'){let str='أنشئ تحضير رياضيات للمرحلة الابتدائية وفق تسلسل الكتاب دون اختصار. استخدم أمثلة تدريجية، وأسئلة وتمارين وعلاج وإثراء، وأخرج JSON واضحًا للمراجعة قبل النشر. الموضوع: '+($('#promptTopic')?.value||'');navigator.clipboard?.writeText(str).then(()=>toast('نُسخ التوجيه')).catch(()=>toast('تعذر النسخ'));return}
if(action==='student-quiz'){$('#kidContent').innerHTML=kidAnswer();$('#kidContent').scrollIntoView({behavior:'smooth'});return}if(action==='student-help'){let q=state.questions[0];$('#kidContent').innerHTML=`<section class="paper"><h3>نفهمها مع بعض</h3><div id="helpSteps">${helpStep(0)}</div></section>`;$('#kidContent').scrollIntoView({behavior:'smooth'});return}if(action.startsWith('help:')){$('#helpSteps').innerHTML=helpStep(Number(action.slice(5)));return}if(action==='student-book'){$('#kidContent').innerHTML=`<div class="paper"><h3>كتابي ودفتري</h3><p class="muted">كتاب الرياضيات يحتاج ملف المنهج الفعلي. إلى أن يُضاف، يمكنك تدوين ملاحظاتك هنا داخل جلسة المعاينة.</p><textarea class="editor" placeholder="اكتبي ماذا تعلّمتِ..."></textarea></div>`;return}
if(action==='export'){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='masaha-backup-'+iso()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(action==='import'){let inp=$('#importJSON');if(!inp){settings();inp=$('#importJSON')}inp?.click();return}if(action==='theme'){state.dark=!state.dark;persist();render();return}}
function helpStep(i){let steps=[['نجرب شيئًا صغيرًا','لو عندك ٣ أقلام وأضفنا ٤ أقلام، نحتاج نعدها كلها.'],['نعد معًا','٣ … ٤، ٥، ٦، ٧. لاحظي كيف زدنا أربعة أعداد.'],['دورك الآن','كم صار مجموع الأقلام؟ ٧ أقلام. أحسنتِ التدرج خطوة خطوة.']];return `<div class="student-scene"><div class="section-kicker">الخطوة ${Math.min(i+1,3)} من ٣</div><h2>${steps[Math.min(i,2)][0]}</h2><p>${steps[Math.min(i,2)][1]}</p>${i<2?button('فهمت، الخطوة التالية','help:'+(i+1),'solid mt'):button('أجرب سؤالًا','student-quiz','solid mt')}</div>`}
const app=$('#app');document.addEventListener('click',e=>{let g=e.target.closest('[data-go]');if(g){go(g.dataset.go);return}let a=e.target.closest('[data-act]');if(a){e.preventDefault();handle(a.dataset.act);return}let task=e.target.closest('[data-toggle-task]');if(task){let t=state.tasks.find(t=>t.id===task.dataset.toggleTask);if(t){if(t.type==='routine')t.doneOn=t.doneOn===iso()?'':iso();else t.done=!t.done;persist();render()}return}let edit=e.target.closest('[data-edit-task]');if(edit){openTask(state.tasks.find(t=>t.id===edit.dataset.editTask));return}let d=e.target.closest('[data-day]');if(d){chosenDay=Number(d.dataset.day);render();return}let c=e.target.closest('[data-class]');if(c){classId=c.dataset.class;render();return}let tt=e.target.closest('[data-tasktab]');if(tt){taskTab=tt.dataset.tasktab;render();return}let k=e.target.closest('[data-kid-answer]');if(k){let q=state.questions[questionIndex%state.questions.length],ok=Number(k.dataset.kidAnswer)===q.correct;$('#answerFeedback').innerHTML=`<div class="notice">${ok?'أحسنتِ! إجابة صحيحة 🌷':'محاولة جميلة، جرّبي مرة ثانية.'}</div>${ok?button('سؤال آخر','next-kid','solid mt'):''}`;return}if(e.target.classList.contains('modal-layer'))close()});document.addEventListener('click',e=>{if(e.target.closest('[data-act="next-kid"]')){questionIndex++;$('#kidContent').innerHTML=kidAnswer()}});
document.addEventListener('submit',e=>{if(e.target.matches('[data-form]')){e.preventDefault();submit(e.target)}});document.addEventListener('change',e=>{let el=e.target;if(el.matches('[data-enrollment]')){state.enrollment[el.dataset.enrollment]=el.value;persist();toast('تم حفظ تفضيل الفصل في المعاينة')}if(el.id==='lessonResourceInput'){saveChosenFiles([...el.files],'lesson')}if(el.id==='mediaInput'){saveChosenFiles([...el.files],'library')}if(el.id==='importJSON'){let f=el.files?.[0];if(f)f.text().then(t=>{let obj=JSON.parse(t);if(!Array.isArray(obj.classes)||!Array.isArray(obj.students)||!Array.isArray(obj.tasks))throw Error();if(confirm('استبدال بيانات هذه المعاينة بنسخة JSON؟')){state={...defs(),...obj};persist();closeSettings();render();toast('تم الاستيراد')}}).catch(()=>toast('ملف بيانات غير صالح'))}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();closeSettings()}});window.addEventListener('storage',e=>{if(e.key===KEY){try{state={...defs(),...JSON.parse(e.newValue)};render()}catch{}}});setInterval(()=>{if(role!=='teacher')return;let c=$('#homeCountdown'),l=timed();if(c&&l.lesson){c.firstChild.textContent=fmt(l.minutes);if(l.minutes<=0)render()}let p=$('#lessonProgress');if(p&&l.active)p.style.width=100*(1-l.minutes/(mins(l.lesson.end)-mins(l.lesson.start)))+'%';let st=$('#studioTimer');if(st&&state.board.timerEnd)st.textContent=fmt((state.board.timerEnd-Date.now())/60000)},1000);persist();try{render()}catch(error){console.error('Masaha initial render failure',error);let el=document.getElementById('app');if(el)el.innerHTML='<main style="margin:32px auto;max-width:720px;padding:24px;font-family:system-ui;direction:rtl;background:white;border-radius:22px"><h1>تعذر تحميل لوحة المعلمة</h1><p>حدث خطأ في تشغيل الواجهة. أعيدي تحديث الصفحة. إذا تكرر، استخدمي رابط التحديث أدناه.</p><a href="?refresh=1">تحديث مساحة</a></main>';}
